-- Financial as-of months use the project timezone, including credit allocations.
begin;
create or replace function private.project_credit(pid uuid,uid uuid,cutoff date default '9999-12-01') returns bigint language sql stable security definer set search_path='' as $$select coalesce((select sum(amount-allocated) from public.project_receipts where project_id=pid and user_id=uid and received_on<cutoff+interval '1 month'),0)-coalesce((select sum(amount) from public.credit_allocations where project_id=pid and user_id=uid and (created_at at time zone 'Asia/Kolkata')::date<cutoff+interval '1 month'),0);$$;
create or replace function private.invoice_card(i public.flat_invoices,cutoff date default '9999-12-01') returns jsonb language sql stable security definer set search_path='' as $$with n as(select coalesce((select sum(a.amount) from public.invoice_adjustments a where invoice_id=i.id and effective_month<=cutoff),0) adjustment,coalesce((select sum(r.allocated) from public.project_receipts r join public.payment_submissions s on s.id=r.submission_id where s.invoice_id=i.id and r.received_on<cutoff+interval '1 month'),0)+coalesce((select sum(amount) from public.credit_allocations where invoice_id=i.id and (created_at at time zone 'Asia/Kolkata')::date<cutoff+interval '1 month'),0) paid) select to_jsonb(i)||jsonb_build_object('month',to_char(p.month,'YYYY-MM'),'state',p.state,'label',f.label,'adjustment',n.adjustment,'paid',n.paid,'balance',i.amount+n.adjustment-n.paid,'status',case when n.paid>=i.amount+n.adjustment then 'paid' when n.paid>0 then 'partially paid' when i.due_date<(now() at time zone 'Asia/Kolkata')::date then 'overdue' else 'due' end,'adjustments',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('created',a.created_at,'effective_month',to_char(a.effective_month,'YYYY-MM'))) from public.invoice_adjustments a where a.invoice_id=i.id and effective_month<=cutoff),'[]')) from public.billing_periods p join public.flats f on f.id=i.flat_id cross join n where p.id=i.period_id;$$;
create or replace function private.project_accounts(pid uuid,m date) returns jsonb language plpgsql stable security definer set search_path='' as $$declare s public.project_settings;bp public.billing_periods;opening bigint;received bigint;paid bigint;transfer bigint;res bigint;expenses bigint;billed bigint;opening_dues bigint;receivable bigint;payable bigint;begin
 select * into s from public.project_settings where project_id=pid;select * into bp from public.billing_periods where project_id=pid and month=m;
 if bp.state='closed' and bp.snapshot is not null then return bp.snapshot;end if;
 select s.opening_cash+coalesce(sum(amount) filter(where fund='general' and paid_on<m),0),coalesce(sum(amount) filter(where fund='general' and paid_on>=m and paid_on<m+interval '1 month' and amount>0 and source not like 'transfer:%'),0),-coalesce(sum(amount) filter(where fund='general' and paid_on>=m and paid_on<m+interval '1 month' and amount<0 and source not like 'transfer:%'),0),coalesce(sum(amount) filter(where fund='general' and paid_on>=m and paid_on<m+interval '1 month' and source like 'transfer:%'),0),s.opening_reserve+coalesce(sum(amount) filter(where fund='reserve' and paid_on<m+interval '1 month'),0) into opening,received,paid,transfer,res from public.project_cash where project_id=pid;
 select coalesce(sum(amount),0) into expenses from public.project_expense_bills where project_id=pid and period=m and status='approved';
 select coalesce(sum(i.amount),0) into billed from public.flat_invoices i join public.billing_periods p on p.id=i.period_id where i.project_id=pid and p.month=m and p.state in ('published','closed');
 billed:=billed+coalesce((select sum(a.amount) from public.invoice_adjustments a join public.flat_invoices i on i.id=a.invoice_id join public.billing_periods p on p.id=i.period_id where a.project_id=pid and a.effective_month=m and p.state in ('published','closed')),0);
 select coalesce(sum((ln->>'amount')::bigint),0) into opening_dues from public.flat_invoices i join public.billing_periods p on p.id=i.period_id cross join lateral jsonb_array_elements(i.lines) ln where i.project_id=pid and p.month=m and p.state in ('published','closed') and ln->>'label'='Verified opening dues';
 billed:=billed-opening_dues;
 select coalesce(sum((private.invoice_card(i,m)->>'balance')::bigint),0) into receivable from public.flat_invoices i join public.billing_periods p on p.id=i.period_id where i.project_id=pid and p.month<=m and p.state in ('published','closed');
 select coalesce(sum(amount),0) into payable from public.project_expense_bills where project_id=pid and period<=m and status='approved';payable:=payable-coalesce((select sum(amount) from public.project_expense_payments where project_id=pid and paid_on<m+interval '1 month'),0);
 return jsonb_build_object('projectId',pid,'month',to_char(m,'YYYY-MM'),'state',coalesce(bp.state,'unbilled'),'opening',opening,'receipts',received,'payments',paid,'closing',opening+received-paid+transfer,'reserveTransfer',transfer,'reserve',res,'advances',coalesce((select sum(amount-allocated) from public.project_receipts where project_id=pid and received_on<m+interval '1 month'),0)-coalesce((select sum(amount) from public.credit_allocations where project_id=pid and (created_at at time zone 'Asia/Kolkata')::date<m+interval '1 month'),0),'receivables',receivable,'payables',payable,'billed',billed,'openingDues',opening_dues,'expenses',expenses,'accrualSurplus',billed-expenses,'categories',coalesce((select jsonb_object_agg(category,total) from (select category,sum(amount) total from public.project_expense_bills where project_id=pid and period=m and status='approved' group by category) x),'{}'),'budgets',coalesce((select jsonb_agg(payload) from public.project_operations where project_id=pid and kind='budget'),'[]'));
 end;$$;
commit;
